import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.history = {}  # opponent_id -> list of (my_action, opp_action)
        self.reputation = {}  # agent_id -> {coop_count, def_count}
        self.generation_round = 0
        self.last_opponent = None
        self.my_coop_rate = {}
        self.opp_coop_rate = {}
        self.memory = {}  # opponent_id -> list of recent 10 actions (bool)

        # Strategic parameters
        self.threshold = 0.4
        self.start_coop = True
        self.probe_round = 5
        self.probed = set()
        self.coop_streak = 0

        # Initialize reputation for all possible agents (we don't know N upfront, but we'll dynamically add)
        pass

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp

        # Initialize memory for opponent if not exists
        if opp not in self.memory:
            self.memory[opp] = []

        # First encounter: start with cooperation to test
        if len(self.memory[opp]) == 0:
            return self.start_coop

        # Get opponent's cooperation rate (recent 10)
        recent_actions = self.memory[opp][-10:]
        if len(recent_actions) == 0:
            coop_rate = 0.5
        else:
            coop_rate = sum(recent_actions) / len(recent_actions)

        # If opponent has cooperated consistently, cooperate
        if coop_rate >= 0.7 and len(self.memory[opp]) >= 3:
            # But occasionally probe to avoid being exploited
            if len(self.memory[opp]) % 10 == 0 and opp not in self.probed:
                self.probed.add(opp)
                return False
            return True

        # If opponent is a consistent defector, defect
        if coop_rate <= 0.3:
            return False

        # Mixed strategy: probabilistic cooperation based on reputation
        # Use reputation from observations
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            if total > 0:
                global_coop = rep.get('coop', 0) / total
            else:
                global_coop = 0.5
        else:
            global_coop = 0.5

        # Combine personal experience and public reputation
        combined = 0.6 * coop_rate + 0.4 * global_coop

        # Threshold-based decision
        if combined > self.threshold:
            # Occasionally defect to test (every 20 rounds)
            if len(self.memory[opp]) % 20 == 0:
                return False
            return True
        else:
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donors and recipients
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['def'] += 1

        # If we are involved, record our interaction
        if donor_id == self.agent_id:
            # We are donor, opponent is recipient
            opp = recipient_id
            my_action = donor_action
            opp_action = recipient_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            # Also store our action? Not needed for memory
        elif recipient_id == self.agent_id:
            # We are recipient, opponent is donor
            opp = donor_id
            my_action = recipient_action
            opp_action = donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)

        # Keep memory bounded (last 30 actions per opponent)
        for opp in list(self.memory.keys()):
            if len(self.memory[opp]) > 30:
                self.memory[opp] = self.memory[opp][-30:]

