class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track interactions observed with each opponent
        # key: opponent_id, value: list of observed tuples (donor_id, donor_action, recipient_id, recipient_action)
        self.history = {}
        # Track my own actions and outcomes against each opponent
        self.my_history = {}
        # Track reputation of each agent (simple score: cooperations - defections)
        self.reputation = {}
        # Track whether I've interacted with each agent before
        self.interacted_with = set()
        # My current strategy: 0 = defect, 1 = cooperate (adaptive)
        self.strategy = 1  # Start cooperative, adapt based on observations

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        # If never interacted before, cooperate initially (but be ready to defect)
        if opponent_id not in self.interacted_with:
            # Use a cooperative start but only if opponent seems cooperative in reputation
            # If opponent has bad reputation, defect immediately
            if self.reputation.get(opponent_id, 0) < -2:
                return False
            return True
        # If we have history, use a modified tit-for-tat with forgiveness
        # Get my last action against this opponent (if any)
        my_last = None
        opp_last = None
        if opponent_id in self.my_history:
            # my_history[opp_id] = list of (my_action, opp_action)
            my_last, opp_last = self.my_history[opponent_id][-1]
        # If opponent defected last time, defect with high probability (but some forgiveness)
        if opp_last == 'defect':
            # Defect unless we have observed them cooperating with others recently
            # Check recent observations: if opponent cooperates often with others, forgive
            coop_count = 0
            total_count = 0
            if opponent_id in self.history:
                # Look at last 10 observations involving this opponent as donor
                obs = [o for o in self.history[opponent_id] if o[0] == opponent_id]
                recent = obs[-10:]
                for o in recent:
                    total_count += 1
                    if o[1] == 'cooperate':
                        coop_count += 1
                if total_count > 0 and coop_count / total_count > 0.7:
                    return True  # forgive if they cooperate with others often
            return False
        # If opponent cooperated last time, cooperate
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation
        if donor_id not in self.reputation:
            self.reputation[donor_id] = 0
        if donor_action == 'cooperate':
            self.reputation[donor_id] += 1
        else:
            self.reputation[donor_id] -= 1
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] += 1
        else:
            self.reputation[recipient_id] -= 1

        # Store observation if donor or recipient is me, or if it's about my opponent
        if donor_id not in self.history:
            self.history[donor_id] = []
        self.history[donor_id].append((donor_id, donor_action, recipient_id, recipient_action))
        if recipient_id not in self.history:
            self.history[recipient_id] = []
        self.history[recipient_id].append((donor_id, donor_action, recipient_id, recipient_action))

        # If I'm involved, update my_history
        if donor_id == self.agent_id:
            if recipient_id not in self.my_history:
                self.my_history[recipient_id] = []
            self.my_history[recipient_id].append((donor_action, recipient_action))
            self.interacted_with.add(recipient_id)
            # Update my strategy based on consequences: if I cooperated and got defect, be more cautious
            if donor_action == 'cooperate' and recipient_action == 'defect':
                # Might switch to defect if this happens often
                if recipient_id in self.my_history and len(self.my_history[recipient_id]) > 2:
                    # Check frequency of betrayal
                    betrayals = sum(1 for a, b in self.my_history[recipient_id] if a == 'cooperate' and b == 'defect')
                    if betrayals / len(self.my_history[recipient_id]) > 0.5:
                        # Defect against this opponent in future
                        pass  # We handle in decide()
        elif recipient_id == self.agent_id:
            if donor_id not in self.my_history:
                self.my_history[donor_id] = []
            self.my_history[donor_id].append((recipient_action, donor_action))  # Note: (my_action, opp_action) but here we are recipient
            self.interacted_with.add(donor_id)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.round_num = 0
        self.gen_round = 0
        self.total_rounds = 143
        self.generation = 0
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.opponent_coop_count = 0
        self.opponent_defect_count = 0
        self.my_actions = []  # list of bools for this generation
        self.opponent_actions = []  # list of bools for this generation
        self.reputation = {}  # agent_id -> {'coop': count, 'defect': count, 'last_action': bool}
        self.cooperation_score = {}  # agent_id -> float (0-1)
        self.last_opponent_action = None
        self.opponent_history = {}  # agent_id -> list of bools (actions as donor)
        self.my_opponent_actions = {}  # agent_id -> list of bools (their actions vs me)
        self.trust_threshold = 0.5
        self.exploit_factor = 0.7
        self.forgiveness = 0.1
        self.defect_frequency = 0.0
        self.coop_frequency = 1.0
        self.last_decisions = []  # recent decisions for adaptation
        self.phase = 0  # 0: explore, 1: exploit
        self.rounds_in_phase = 0
        self.phase_length = 20
        self.personal_coop_rate = 0.5
        self.opponent_coop_rates = {}
        self.my_score = 0
        self.opponent_scores = {}
        self.known_cooperators = set()
        self.known_defectors = set()
        self.initial_trust = 0.5
        self.mistake_threshold = 0.2
        self.adaptation_rate = 0.1

    def decide(self) -> bool:
        if self.opponent_id is None:
            return False  # defect if no opponent
        self.round_num += 1
        self.gen_round += 1

        # Update phase based on generation and round
        if self.generation < 30:
            # Early generation: explore and build reputation
            self.phase = 0
            self.phase_length = 30
        elif self.generation < 70:
            # Middle: more cooperative if reputation good
            self.phase = 1
            self.phase_length = 20
        else:
            # Late: exploit any known weaknesses
            self.phase = 2
            self.phase_length = 15

        if self.rounds_in_phase >= self.phase_length:
            self.rounds_in_phase = 0
            if self.phase == 0:
                self.phase = 1
            elif self.phase == 1:
                self.phase = 2
            else:
                self.phase = 0

        opp_id = self.opponent_id

        # Get opponent's cooperation rate
        opp_coop_rate = self.cooperation_score.get(opp_id, self.initial_trust)

        # My current reputation (if I've been cooperating a lot, cooperate more)
        my_reputation = self.cooperation_score.get(self.agent_id, self.initial_trust)

        # Strategy logic
        decision = False  # defect by default

        if self.phase == 0:
            # Exploration: try to cooperate initially, but defect if opponent defects often
            if opp_coop_rate > 0.4:
                decision = True
            else:
                decision = random.random() < 0.3
        elif self.phase == 1:
            # Middle: cooperate if opponent is cooperative, defect if they're not
            if opp_coop_rate > 0.5:
                decision = True
            else:
                decision = False
        else:
            # Late: exploit if opponent is naive, cooperate with strong cooperators
            if opp_coop_rate > 0.7:
                decision = True
            elif opp_coop_rate > 0.3:
                # Mixed: defect sometimes to exploit
                decision = random.random() > 0.4
            else:
                decision = False

        # If I've been defecting a lot, maybe try to cooperate to rebuild reputation
        if self.my_defect_count > 20 and self.my_coop_count < 10:
            if random.random() < 0.2:
                decision = True

        # Simple tit-for-tat with forgiveness
        if self.last_opponent_action is not None:
            if self.last_opponent_action is False:
                if random.random() < self.forgiveness:
                    decision = True
                else:
                    decision = False

        # If opponent has a very bad reputation, always defect
        if opp_coop_rate < 0.2:
            decision = False

        # Store decision
        self.last_decisions.append(decision)
        if len(self.last_decisions) > 20:
            self.last_decisions.pop(0)

        # Count actions (will be updated in observe)
        if decision:
            self.my_coop_count += 1
        else:
            self.my_defect_count += 1

        self.rounds_in_phase += 1
        return decision

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'

        # Update reputation for donor
        if donor_id not in self.reputation:
            self.reputation[donor_id] = {'coop': 0, 'defect': 0, 'last_action': None}
        self.reputation[donor_id]['last_action'] = donor_coop
        if donor_coop:
            self.reputation[donor_id]['coop'] += 1
        else:
            self.reputation[donor_id]['defect'] += 1

        # Update cooperation score
        total = self.reputation[donor_id]['coop'] + self.reputation[donor_id]['defect']
        if total > 0:
            self.cooperation_score[donor_id] = self.reputation[donor_id]['coop'] / total

        # Update my own action tracking
        if donor_id == self.agent_id:
            self.my_actions.append(donor_coop)
            if donor_coop:
                self.my_coop_count += 1
            else:
                self.my_defect_count += 1

        # Track opponent actions
        if recipient_id == self.agent_id:
            # This is an action directed at me
            if donor_id not in self.opponent_history:
                self.opponent_history[donor_id] = []
            self.opponent_history[donor_id].append(donor_coop)
            if donor_coop:
                self.opponent_coop_count += 1
            else:
                self.opponent_defect_count += 1
            self.last_opponent_action = donor_coop
            if donor_id not in self.my_opponent_actions:
                self.my_opponent_actions[donor_id] = []
            self.my_opponent_actions[donor_id].append(donor_coop)

        # Track actions when I'm donor
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            # I acted, update my reputation
            pass

        # Track opponent cooperation rates
        if donor_id not in self.opponent_coop_rates:
            self.opponent_coop_rates[donor_id] = {'coop': 0, 'defect': 0}
        if donor_coop:
            self.opponent_coop_rates[donor_id]['coop'] += 1
        else:
            self.opponent_coop_rates[donor_id]['defect'] += 1

        # Classify agents
        coop_rate = self.cooperation_score.get(donor_id, 0.5)
        if coop_rate > 0.6:
            self.known_cooperators.add(donor_id)
            self.known_defectors.discard(donor_id)
        elif coop_rate < 0.4:
            self.known_defectors.add(donor_id)
            self.known_cooperators.discard(donor_id)

        # Update generation counter if needed
        if self.gen_round >= self.total_rounds:
            self.generation += 1
            self.gen_round = 0
            self.my_actions = []
            self.opponent_actions = []
            self.my_coop_count = 0
            self.my_defect_count = 0
            self.opponent_coop_count = 0
            self.opponent_defect_count = 0
            self.last_opponent_action = None

