import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.generation_round = 0
        self.generation = 0
        self.total_actions = {}
        self.coop_counts = {}
        self.defect_counts = {}
        self.my_last_action = None
        self.opp_last_action = None
        self.opp_history = {}
        self.my_history = []
        self.round_num = 0
        self.memory = {}
        self.trust = {}
        self.coop_streak = 0
        self.defect_streak = 0
        self.opp_coop_streak = 0
        self.opp_defect_streak = 0

    def decide(self) -> bool:
        if self.opponent_id is None:
            return False

        # Track rounds in generation (reset externally? we don't know, so use round counter)
        self.round_num += 1

        # Initialize opponent stats if needed
        if self.opponent_id not in self.total_actions:
            self.total_actions[self.opponent_id] = 0
            self.coop_counts[self.opponent_id] = 0
            self.defect_counts[self.opponent_id] = 0
            self.opp_history[self.opponent_id] = []
            self.trust[self.opponent_id] = 0.5

        # Simple strategy: cooperate if opponent has cooperated more than defected historically
        # and we have interacted enough; otherwise defect.
        # But also add randomness to avoid being too predictable.

        opp_total = self.total_actions.get(self.opponent_id, 0)
        opp_coop = self.coop_counts.get(self.opponent_id, 0)

        if opp_total < 3:
            # Early game: cooperate with probability 0.7 to build trust, but defect sometimes
            return random.random() < 0.7
        else:
            coop_ratio = opp_coop / opp_total
            # If opponent cooperates more than 50%, cooperate; else defect
            # Add slight randomness to avoid deterministic patterns
            if coop_ratio > 0.5:
                return random.random() < 0.9  # mostly cooperate
            else:
                return random.random() < 0.1  # mostly defect

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation tracking for all agents
        # Track each agent's actions in general
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.total_actions:
                self.total_actions[agent_id] = 0
                self.coop_counts[agent_id] = 0
                self.defect_counts[agent_id] = 0
                self.opp_history[agent_id] = []
                self.trust[agent_id] = 0.5
            self.total_actions[agent_id] += 1
            if action == 'cooperate':
                self.coop_counts[agent_id] += 1
            else:
                self.defect_counts[agent_id] += 1
            self.opp_history[agent_id].append(action)

        # Update my own history
        if donor_id == self.agent_id:
            self.my_last_action = donor_action
            self.my_history.append(donor_action)
            if donor_action == 'cooperate':
                self.coop_streak += 1
                self.defect_streak = 0
            else:
                self.defect_streak += 1
                self.coop_streak = 0
        if recipient_id == self.agent_id:
            # If I'm recipient, update opponent's action toward me
            pass

        # Update opponent-specific history if I'm involved
        if donor_id == self.agent_id and recipient_id == self.opponent_id:
            self.opp_last_action = recipient_action
        if donor_id == self.opponent_id and recipient_id == self.agent_id:
            self.opp_last_action = donor_action

        # Update trust based on observed actions (simple heuristic)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.trust:
                self.trust[agent_id] = 0.5
            if action == 'cooperate':
                self.trust[agent_id] = self.trust[agent_id] * 0.9 + 0.1  # increase slightly
            else:
                self.trust[agent_id] = self.trust[agent_id] * 0.9  # decrease

