        self.coop_count = {}
        self.defect_count = {}
        # Track interactions with each agent: list of (my_action, opp_action) tuples
        self.history = {}
        # Track opponent's last action against me
        self.last_opp_action = None
        # Track if I have cooperated with each agent recently (for forgiveness)
        self.coop_with = {}
        # Parameters for adaptive strategy
        self.cooperation_threshold = 0.5  # initial threshold for trusting based on reputation
        self.defection_penalty = 2  # how much a defection affects reputation weight
        self.cooperation_bonus = 1  # how much a cooperation affects reputation weight
        self.memory_length = 50  # how many recent observations to consider
        self.recent_actions = []  # list of (donor, action, recipient) for recent observations
        self.rounds_played = 0
        self.my_last_action = True  # default cooperate first

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id
        if opp_id not in self.history:
            self.history[opp_id] = []
        # Start with cooperation if no history, but defect if opponent defected last time we played
        if not self.history[opp_id]:
            # First interaction: cooperate initially to test
            return True

        # Get opponent's reputation score based on observed actions
        rep_score = self._get_reputation(opp_id)

        # Check if opponent has defected against me recently
        recent_defect = False
        for my_act, opp_act in self.history[opp_id][-5:]:
            if not opp_act:
                recent_defect = True
                break

        # Strategy: cooperate if opponent has good reputation and hasn't defected recently
        if rep_score >= self.cooperation_threshold and not recent_defect:
            return True
        else:
            # If opponent is unreliable, defect
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for reputation
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # Store recent observations (limited length)
        self.recent_actions.append((donor_id, donor_action, recipient_id, recipient_action))
        if len(self.recent_actions) > self.memory_length * 2:
            self.recent_actions = self.recent_actions[-(self.memory_length * 2):]

        # Update my history if I am involved
        if donor_id == self.agent_id:
            self.history.setdefault(recipient_id, []).append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.last_opp_action = recipient_action == 'cooperate'
        elif recipient_id == self.agent_id:
            self.history.setdefault(donor_id, []).append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.last_opp_action = donor_action == 'cooperate'

        # Update reputation threshold based on my own experiences (simple adaptation)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # If I was exploited, lower my trust threshold to be more cautious
            if donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'defect':
                self.cooperation_threshold = max(0.1, self.cooperation_threshold - 0.05)
            elif recipient_id == self.agent_id and recipient_action == 'cooperate' and donor_action == 'defect':
                self.cooperation_threshold = max(0.1, self.cooperation_threshold - 0.05)
            # If I cooperated and was reciprocated, raise threshold slightly
            elif donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.cooperation_threshold = min(0.9, self.cooperation_threshold + 0.01)
            elif recipient_id == self.agent_id and recipient_action == 'cooperate' and donor_action == 'cooperate':
                self.cooperation_threshold = min(0.9, self.cooperation_threshold + 0.01)

    def _get_reputation(self, agent_id: int) -> float:
        # Compute a reputation score based on recent observations
        total_actions = 0
        coop_score = 0
        for donor, action, recipient, recip_action in self.recent_actions[-self.memory_length:]:
            if donor == agent_id:
                total_actions += 1
                if action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
            if recipient == agent_id:
                total_actions += 1
                if recip_action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
        if total_actions == 0:
            return 0.5  # neutral if no data
        # Normalize to roughly -1 to 1 range, then map to 0-1
        normalized = coop_score / (total_actions * max(self.defection_penalty, self.cooperation_bonus))
        return max(0.0, min(1.0, (normalized + 1) / 2))

