        self.seen = set()
        for i in range(15):
            self.reputation[i] = 0.5
            self.coop_count[i] = 0
            self.defect_count[i] = 0
        # Track my own reputation (as observed by others) - we can't see it directly, but we can infer from interactions
        self.my_reputation_estimate = 0.5
        # Memory of recent actions for pattern detection
        self.recent_opponent_actions = {}  # opponent_id -> deque of (action, round)
        # Track if I've been exploited (opponent defected when I cooperated)
        self.exploited = {}  # opponent_id -> count

    def decide(self) -> bool:
        opp = getattr(self, '_ctx_opponent_id', None)
        if opp is None:
            return False
        self.round_num += 1

        # Direct interaction history
        direct_interactions = self.interactions.get(opp, 0)
        my_obs = self.opponent_actions.get(opp, [])
        my_coop_rate = sum(my_obs) / len(my_obs) if my_obs else 0.5

        # Public reputation
        opp_reputation = self.reputation.get(opp, 0.5)
        total_public = self.coop_count.get(opp, 0) + self.defect_count.get(opp, 0)
        public_coop_rate = self.coop_count.get(opp, 0) / total_public if total_public > 0 else 0.5

        # Combine with more weight on direct observation after enough interactions
        if direct_interactions > 0:
            weight_direct = min(0.8, 0.2 + 0.05 * direct_interactions)
            combined_rate = weight_direct * my_coop_rate + (1 - weight_direct) * public_coop_rate
        else:
            combined_rate = public_coop_rate

        # First encounter strategy: be selectively cooperative
        if direct_interactions == 0:
            # Cooperate if reputation is decent, but defect against known defectors
            if opp_reputation >= 0.45:
                return True
            else:
                return False

        # Pattern detection: if opponent has a recent streak of defections, defect
        recent_actions = self.recent_opponent_actions.get(opp, deque(maxlen=10))
        if len(recent_actions) >= 3 and sum(1 for a in recent_actions if not a) >= 2:
            return False

        # Forgiving: if opponent cooperated last time and has good reputation, cooperate
        # Exploit: if opponent is too trusting (always cooperate), defect more often
        if my_coop_rate > 0.9 and opp_reputation > 0.8:
            # They are very cooperative and have good reputation -> exploit them
            return random.random() < 0.7  # 70% defect to exploit

        # Standard adaptive strategy
        if combined_rate < 0.25:
            return False
        elif combined_rate < 0.45:
            # Mixed: defect more often
            return random.random() < 0.3
        elif combined_rate < 0.7:
            # Balanced
            return random.random() < 0.6
        else:
            # Cooperate mostly, but occasionally defect to avoid being exploited
            if random.random() < 0.95:
                return True
            else:
                return False

