        elif recipient_id == self.agent_id:
            opp = donor_id
            self.opponent_actions.setdefault(opp, []).append(donor_action == 'cooperate')
            self.my_actions.setdefault(opp, []).append(recipient_action == 'cooperate')
            self.interactions[opp] = self.interactions.get(opp, 0) + 1
            self.last_my_action[opp] = recipient_action == 'cooperate'
            # Track if exploited
            if recipient_action == 'cooperate' and donor_action == 'defect':
                self.exploited[opp] = self.exploited.get(opp, 0) + 1
            self.recent_opponent_actions.setdefault(opp, deque(maxlen=10)).append(donor_action == 'cooperate')
        else:
            # Third-party observation: just update reputation already done
            pass

