    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.history = {}
        self.reputation = {}
        self.generation_round = 0
        self.last_opponent = None
        self.my_coop_rate = {}
        self.opp_coop_rate = {}
        self.memory = {}
        self.threshold = 0.5
        self.start_coop = True
        self.probe_round = 5
        self.probed = set()
        self.coop_streak = 0
        self.defection_count = {}
        self.cooperation_count = {}
        self.reputation_self = {'coop': 0, 'def': 0}
        self.opponent_actions = {}
        self.defect_against_defectors = True
        self.opp_public_behavior = {}
        self.own_actions = []
        self.own_payoffs = []
        self.exploited = set()
        # New: track opponent's reputation trend and our own recent outcomes
        self.opp_rep_trend = {}
        self.recent_outcomes = []
        self.defect_streak = 0
        self.coop_streak = 0
        self.last_action = None
        self.exploit_timer = {}  # rounds since last exploit against an opponent

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []
        if opp not in self.opp_public_behavior:
            self.opp_public_behavior[opp] = {'coop': 0, 'def': 0}
        if opp not in self.opp_rep_trend:
            self.opp_rep_trend[opp] = []
        if opp not in self.exploit_timer:
            self.exploit_timer[opp] = 0

        # First encounter: cooperate to build trust and gain reputation
        if len(self.memory[opp]) == 0:
            return True

        # Get opponent's cooperation rate (personal experience)
        recent_actions = self.memory[opp][-10:]
        if len(recent_actions) == 0:
            coop_rate = 0.5
        else:
            coop_rate = sum(recent_actions) / len(recent_actions)

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Combine personal experience and public reputation
        combined = 0.6 * coop_rate + 0.4 * public_coop

        # If opponent has defected against us specifically, be more cautious
        if self.defection_count[opp] > 0:
            combined *= 0.8

        # NEW: Exploitation strategy - if opponent is highly cooperative and we've never exploited them,
        # defect to gain short-term advantage, but not too often to ruin reputation
        # Also exploit only if we have a good reputation and haven't been punished recently
        if combined > 0.85 and opp not in self.exploited:
            total_self = self.reputation_self['coop'] + self.reputation_self['def']
            self_rep = self.reputation_self['coop'] / total_self if total_self > 0 else 0.5
            # Check our recent performance - if we're losing, don't risk exploitation
            if self_rep > 0.7 and len(self.recent_outcomes) >= 5:
                recent_avg = sum(self.recent_outcomes[-5:]) / 5
                if recent_avg > 0.2:  # only exploit if recent payoffs are positive
                    self.exploited.add(opp)
                    self.exploit_timer[opp] = 0
                    return False

        # Strong cooperation signal but not exploitable: cooperate
        if combined > 0.8:
            return True

        # Strong defection signal: defect
        if combined < 0.3:
            return False

        # Mixed: probabilistic decision
        # Slightly favor cooperation but with some randomness
        # Also adjust based on our recent success - if we've been doing well, be more cooperative
        if len(self.recent_outcomes) >= 5:
            recent_avg = sum(self.recent_outcomes[-5:]) / 5
            if recent_avg > 0.5:
                return random.random() < 0.8
            else:
                return random.random() < 0.25
        else:
            if combined > 0.5:
                return random.random() < 0.7
            else:
                return random.random() < 0.3
        return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
                # Track reputation trend
                if agent_id not in self.opp_rep_trend:
                    self.opp_rep_trend[agent_id] = []
                self.opp_rep_trend[agent_id].append(1)
            else:
                self.reputation[agent_id]['def'] += 1
                if agent_id not in self.opp_rep_trend:
                    self.opp_rep_trend[agent_id] = []
                self.opp_rep_trend[agent_id].append(0)
            # Keep trend bounded
            if agent_id in self.opp_rep_trend and len(self.opp_rep_trend[agent_id]) > 20:
                self.opp_rep_trend[agent_id] = self.opp_rep_trend[agent_id][-20:]

        # Track our own reputation
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.reputation_self['coop'] += 1
            else:
                self.reputation_self['def'] += 1
        elif recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation_self['coop'] += 1
            else:
                self.reputation_self['def'] += 1

        # Record interactions where we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Determine opponent and their action
            if donor_id == self.agent_id:
                opp = recipient_id
                opp_action = recipient_action
                my_action = donor_action
            else:
                opp = donor_id
                opp_action = donor_action
                my_action = recipient_action

            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            # Track our own action
            self.own_actions.append(1 if my_action == 'cooperate' else 0)
            # Compute payoff for this interaction
            if my_action == 'cooperate' and opp_action == 'cooperate':
                payoff = 1
            elif my_action == 'cooperate' and opp_action == 'defect':
                payoff = -1
            elif my_action == 'defect' and opp_action == 'cooperate':
                payoff = 2
            else:
                payoff = 0
            self.own_payoffs.append(payoff)
            self.recent_outcomes.append(payoff)
            # Track exploit timer
            if opp in self.exploit_timer:
                self.exploit_timer[opp] += 1
            # If opponent retaliates after we defected, remove from exploited set
            if my_action == 'defect' and opp_action == 'defect' and opp in self.exploited:
                self.exploited.discard(opp)
                self.exploit_timer[opp] = 0

        # Update public behavior tracking (how opponent treats others)
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.opp_public_behavior:
                    self.opp_public_behavior[agent_id] = {'coop': 0, 'def': 0}
                if action == 'cooperate':
                    self.opp_public_behavior[agent_id]['coop'] += 1
                else:
                    self.opp_public_behavior[agent_id]['def'] += 1

        # Keep memory bounded
        for opp in list(self.memory.keys()):
            if len(self.memory[opp]) > 30:
                self.memory[opp] = self.memory[opp][-30:]

        # Keep own action history bounded
        if len(self.own_actions) > 100:
            self.own_actions = self.own_actions[-100:]
            self.own_payoffs = self.own_payoffs[-100:]
        if len(self.recent_outcomes) > 20:
            self.recent_outcomes = self.recent_outcomes[-20:]

        # Adjust exploitation set dynamically
        # If we've been exploited and losing, reset exploitation targets
        if len(self.recent_outcomes) >= 10:
            recent_avg = sum(self.recent_outcomes[-10:]) / 10
            if recent_avg < -0.2:
                self.exploited = set()
            # If we've been exploiting and it's going well, keep exploiting but vary targets
            if recent_avg > 0.5:
                # Occasionally try new exploitation targets
                if random.random() < 0.1:
                    # Pick a random opponent from memory to potentially exploit
                    if self.memory:
                        candidate = random.choice(list(self.memory.keys()))
                        if candidate not in self.exploited:
                            self.exploited.add(candidate)
                            self.exploit_timer[candidate] = 0

        # Clean up exploit_timer for opponents no longer in memory
        for opp in list(self.exploit_timer.keys()):
            if opp not in self.memory:
                del self.exploit_timer[opp]

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.generation = 0
        self.round = 0
        self.coop_count = {}
        self.defect_count = {}
        self.history = {}
        self.last_opp_action = None
        self.coop_with = {}
        self.cooperation_threshold = 0.5
        self.defection_penalty = 2
        self.cooperation_bonus = 1
        self.memory_length = 50
        self.recent_actions = []
        self.rounds_played = 0
        self.my_last_action = True
        self.opponent_round = {}
        self.my_rep = 0.5
        self.own_coop = 0
        self.own_defect = 0
        # New state for improved strategy
        self.baseline_rep = 0.5
        self.coop_streak = 0
        self.defect_streak = 0
        self.exploit_mode = False
        self.exploit_targets = set()
        # Additional state for improved reputation management
        self.defect_since_coop = 0
        self.coop_since_defect = 0
        self.last_opponent_defected = False
        self.defect_after_coop = 0
        self.coop_after_defect = 0
        self.opponent_coop_rates = {}

    def decide(self) -> bool:
        opp_id = self._ctx_opponent_id
        if opp_id not in self.history:
            self.history[opp_id] = []
        if not self.history[opp_id]:
            return True

        recent_defect = any(not opp_act for my_act, opp_act in self.history[opp_id][-3:])
        rep = self._get_reputation(opp_id)

        # If opponent has defected recently, defect unless they have very high rep and I am desperate
        if recent_defect and rep < 0.8:
            return False

        # Track opponent's pattern: if they cooperate in first half, exploit in second half
        h = self.history[opp_id]
        if len(h) >= 6:
            first_half_coop = sum(1 for a, b in h[:len(h)//2] if b)
            second_half_def = sum(1 for a, b in h[len(h)//2:] if not b)
            if first_half_coop > len(h)//2 * 0.8 and second_half_def > 0:
                # They are exploitable: cooperate early, defect later
                if len(h) % 2 == 0:
                    return True
                else:
                    return False

        # New: Exploit known cooperators more aggressively
        if opp_id in self.exploit_targets and rep > 0.7:
            # Cooperate to keep them cooperative, but defect occasionally
            if random.random() < 0.5:
                return True
            else:
                return False

        # New: Strategic reputation manipulation - alternate to build rep then defect
        # If my reputation is low, cooperate more to raise it
        if self.my_rep < 0.3 and not recent_defect:
            return True

        # If I have a long coop streak, occasionally defect to seize gains
        if self.coop_streak >= 10 and random.random() < 0.2:
            return False

        # Default: cooperate if reputation decent and no recent defect
        if rep >= 0.4 and not recent_defect:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1
        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        self.recent_actions.append((donor_id, donor_action, recipient_id, recipient_action))
        if len(self.recent_actions) > self.memory_length * 2:
            self.recent_actions = self.recent_actions[-(self.memory_length * 2):]

        if donor_id == self.agent_id:
            self.history.setdefault(recipient_id, []).append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.last_opp_action = recipient_action == 'cooperate'
            if donor_action == 'cooperate':
                self.own_coop += 1
                self.coop_streak += 1
                self.defect_streak = 0
                self.coop_since_defect += 1
            else:
                self.own_defect += 1
                self.defect_streak += 1
                self.coop_streak = 0
                self.defect_since_coop += 1
            # Track opponent reaction to my actions
            if donor_action == 'cooperate' and recipient_action == 'defect':
                self.defect_after_coop += 1
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self.coop_after_defect += 1
        elif recipient_id == self.agent_id:
            self.history.setdefault(donor_id, []).append((donor_action == 'cooperate', recipient_action == 'cooperate'))
            self.last_opp_action = donor_action == 'cooperate'

        # Update own reputation estimate from observations
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.my_rep = min(1.0, self.my_rep + 0.02)
            else:
                self.my_rep = max(0.0, self.my_rep - 0.05)
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.my_rep = min(1.0, self.my_rep + 0.02)
            else:
                self.my_rep = max(0.0, self.my_rep - 0.05)

        # Adaptive threshold: if I defect and get punished, be more cautious
        if donor_id == self.agent_id and donor_action == 'defect' and recipient_action == 'defect':
            self.cooperation_threshold = min(0.9, self.cooperation_threshold + 0.02)
        elif donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.cooperation_threshold = max(0.1, self.cooperation_threshold - 0.01)

        # New: Detect and track cooperative opponents for exploitation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                # Both cooperated - potential cooperator
                self._update_coop_tracker(donor_id, True)
                self._update_coop_tracker(recipient_id, True)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                # Donor cooperated against defector - likely cooperator
                self._update_coop_tracker(donor_id, True)
                self._update_coop_tracker(recipient_id, False)
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                self._update_coop_tracker(donor_id, False)
                self._update_coop_tracker(recipient_id, True)

        # Track my own success to adjust exploitation behavior
        if donor_id == self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.baseline_rep = min(1.0, self.baseline_rep + 0.01)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.baseline_rep = max(0.0, self.baseline_rep - 0.02)

        # Update opponent cooperation rates for more targeted decisions
        if donor_id != self.agent_id:
            if donor_id not in self.opponent_coop_rates:
                self.opponent_coop_rates[donor_id] = [0, 0]
            if donor_action == 'cooperate':
                self.opponent_coop_rates[donor_id][0] += 1
            self.opponent_coop_rates[donor_id][1] += 1
        if recipient_id != self.agent_id:
            if recipient_id not in self.opponent_coop_rates:
                self.opponent_coop_rates[recipient_id] = [0, 0]
            if recipient_action == 'cooperate':
                self.opponent_coop_rates[recipient_id][0] += 1
            self.opponent_coop_rates[recipient_id][1] += 1

    def _update_coop_tracker(self, agent_id: int, cooperated: bool) -> None:
        if agent_id not in self.coop_with:
            self.coop_with[agent_id] = [0, 0]  # [coops, total]
        if cooperated:
            self.coop_with[agent_id][0] += 1
        self.coop_with[agent_id][1] += 1
        # If they cooperate more than 70% of observed interactions, mark as exploitable
        if self.coop_with[agent_id][1] >= 5 and self.coop_with[agent_id][0] / self.coop_with[agent_id][1] > 0.7:
            self.exploit_targets.add(agent_id)

    def _get_reputation(self, agent_id: int) -> float:
        total_actions = 0
        coop_score = 0
        # Use longer memory for more stable reputation
        lookback = min(len(self.recent_actions), self.memory_length * 2)
        for donor, action, recipient, recip_action in self.recent_actions[-lookback:]:
            if donor == agent_id:
                total_actions += 1
                if action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
            if recipient == agent_id:
                total_actions += 1
                if recip_action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
        if total_actions == 0:
            return 0.5
        normalized = coop_score / (total_actions * max(self.defection_penalty, self.cooperation_bonus))
        return max(0.0, min(1.0, (normalized + 1) / 2))

