        # New: track known cooperators vs defectors
        self.known_cooperators = set()
        self.known_defectors = set()
        self.cooldown_opponents = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []
        if opp not in self.recent_opponent_actions:
            self.recent_opponent_actions[opp] = []
        if opp not in self.cooldown_opponents:
            self.cooldown_opponents[opp] = 0

        # Cooldown: if we just defected against this opponent, 
        # try to rebuild trust with a cooperation sometimes
        if self.cooldown_opponents[opp] > 0:
            self.cooldown_opponents[opp] -= 1

