        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Combine personal experience and public reputation
        combined = 0.7 * coop_rate + 0.3 * public_coop

        # If opponent has defected against us specifically, be more cautious
        if self.defection_count[opp] > 0:
            combined *= 0.7

        # Short-term trend: if opponent recently defected, be more suspicious
        if short_coop < 0.5:
            combined *= 0.8

        # Strong cooperation signal: high coop rate and positive reputation
        if combined > 0.85:
            return True

        # Strong defection signal: low coop rate or negative reputation
        if combined < 0.25:
            # Occasionally probe even against defectors to test if they changed
            if random.random() < 0.1:
                return True
            return False

        # Mixed: probabilistic decision with exploitation strategy
        # If this opponent is a known cooperator (high coop rate), 
        # sometimes defect to exploit them while risking reputation
        if opp in self.known_cooperators and combined > 0.7:
            # Exploit with some probability - but not too often to avoid ruining reputation
            if random.random() < 0.2:
