        if recipient_action == 'defect':
            self.recent_defectors.add(recipient_id)
        # Remove old defectors after some rounds
        if len(self.recent_defectors) > 10:
            # Simplify: just clear and rebuild from recent actions
            self.recent_defectors = set()
            for d, act, r, ract in self.recent_actions[-self.memory_length:]:
                if act == 'defect':
                    self.recent_defectors.add(d)
                if ract == 'defect':
                    self.recent_defectors.add(r)

        # Update own reputation estimate from observations
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.coop_reputation = min(1.0, self.coop_reputation + 0.03)
            else:
                self.coop_reputation = max(0.0, self.coop_reputation - 0.05)
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_reputation = min(1.0, self.coop_reputation + 0.03)
            else:
                self.coop_reputation = max(0.0, self.coop_reputation - 0.05)

        # Adaptive threshold: if I defect and get punished, be more cautious
        if donor_id == self.agent_id and donor_action == 'defect' and recipient_action == 'defect':
            self.cooperation_threshold = min(0.9, self.cooperation_threshold + 0.02)
            self.defection_probability = min(0.5, self.defection_probability + self.defection_learning_rate)
        elif donor_id == self.agent_id and donor_action == 'cooperate' and recipient_action == 'cooperate':
            self.cooperation_threshold = max(0.1, self.cooperation_threshold - 0.01)
            self.cooperation_probability = min(0.95, self.cooperation_probability + self.cooperation_learning_rate)

        # Track cooperative opponents for exploitation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Update coop rates for both agents
            self._update_coop_tracker(donor_id, donor_action == 'cooperate')
            self._update_coop_tracker(recipient_id, recipient_action == 'cooperate')
            # Mark defectors as not exploitable
            if donor_action == 'defect':
                self._mark_as_defector(donor_id)
            if recipient_action == 'defect':
                self._mark_as_defector(recipient_id)

        # Track my own success to adjust exploitation behavior
        if donor_id == self.agent_id:
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.baseline_rep = min(1.0, self.baseline_rep + 0.01)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.baseline_rep = max(0.0, self.baseline_rep - 0.02)

        # New: Track opponent interactions for all observations to build better models
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # We observe others' interactions, update their cooperation rates
            self._update_coop_tracker(donor_id, donor_action == 'cooperate')
            self._update_coop_tracker(recipient_id, recipient_action == 'cooperate')
            # Update recent defectors based on observations
            if donor_action == 'defect':
                self.recent_defectors.add(donor_id)
            if recipient_action == 'defect':
                self.recent_defectors.add(recipient_id)

    def _update_coop_tracker(self, agent_id: int, cooperated: bool) -> None:
        if agent_id not in self.coop_with:
            self.coop_with[agent_id] = [0, 0]  # [coops, total]
        if cooperated:
            self.coop_with[agent_id][0] += 1
        self.coop_with[agent_id][1] += 1
        # If they cooperate more than 70% of observed interactions, mark as exploitable
        if self.coop_with[agent_id][1] >= 5 and self.coop_with[agent_id][0] / self.coop_with[agent_id][1] > 0.7:
            self.exploit_targets.add(agent_id)
        # If they defect more than 50% of observed interactions, mark as defector
        if self.coop_with[agent_id][1] >= 5 and self.coop_with[agent_id][0] / self.coop_with[agent_id][1] < 0.5:
            self.recent_defectors.add(agent_id)

    def _mark_as_defector(self, agent_id: int) -> None:
        # Remove from exploit targets if they defect
        self.exploit_targets.discard(agent_id)
        # Ensure coop_with tracks them as defector
        if agent_id not in self.coop_with:
            self.coop_with[agent_id] = [0, 0]
        self.coop_with[agent_id][1] += 1

    def _update_reputation_estimate(self) -> None:
        # Decay vengeance mode over time
        if self.vengeance_mode and self.rounds_since_last_defect >= self.forgiveness_rounds:
            self.vengeance_mode = False
        # Decay reputation slightly over time
        self.coop_reputation *= self.reputation_decay

    def _get_reputation(self, agent_id: int) -> float:
        total_actions = 0
        coop_score = 0
        # Use longer memory for more stable reputation
        lookback = min(len(self.recent_actions), self.memory_length * 2)
        for donor, action, recipient, recip_action in self.recent_actions[-lookback:]:
            if donor == agent_id:
                total_actions += 1
                if action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
            if recipient == agent_id:
                total_actions += 1
                if recip_action == 'cooperate':
                    coop_score += self.cooperation_bonus
                else:
                    coop_score -= self.defection_penalty
        if total_actions == 0:
            return 0.5
        normalized = coop_score / (total_actions * max(self.defection_penalty, self.cooperation_bonus))
        return max(0.0, min(1.0, (normalized + 1) / 2))

