        else:
            my_coop_rate = 0.5

        # Combine rates with adaptive weighting
        if direct_interactions > 0:
            weight_direct = min(0.85, 0.2 + 0.15 * direct_interactions)
            combined_rate = weight_direct * my_coop_rate + (1 - weight_direct) * coop_rate
        else:
            combined_rate = coop_rate

        # Check for recent defection retaliation patterns
        last_def = self.last_defect_round.get(opp, -100)
