        if opp not in self.coop_after_def:
            self.coop_after_def[opp] = 0
        if opp not in self.recent_defections:
            self.recent_defections[opp] = 0

        # First encounter: cooperate to build trust
        if len(self.memory[opp]) == 0:
            return True

        # Get opponent's cooperation rate from personal experience
        recent_actions = self.memory[opp][-15:]
        if len(recent_actions) == 0:
            coop_rate = 0.5
        else:
            coop_rate = sum(recent_actions) / len(recent_actions)

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Combine personal experience and public reputation
        if len(self.memory[opp]) >= 5:
            combined = 0.7 * coop_rate + 0.3 * public_coop
        else:
            combined = 0.5 * coop_rate + 0.5 * public_coop

        # If opponent has defected against us recently, be more cautious
        if self.recent_defections[opp] > 0:
            combined *= 0.8

        # Get our own public reputation
        total_self = self.reputation_self['coop'] + self.reputation_self['def']
        self_rep = self.reputation_self['coop'] / total_self if total_self > 0 else 0.5

        # Check our recent performance
        if len(self.recent_outcomes) >= 5:
            recent_avg = sum(self.recent_outcomes[-5:]) / 5
        else:
            recent_avg = 0

        # Enhanced exploitation: only exploit if we have strong reputation advantage
        # and opponent is very cooperative, but with longer cooldown
        if combined > 0.92 and opp not in self.exploited and self_rep > 0.8:
            # Only exploit if we haven't exploited this opponent in last 5 rounds
            if opp not in self.last_exploit_round or self.round_counter - self.last_exploit_round[opp] > 5:
                # Exploit only if we're doing well overall
                if recent_avg > 0.2:
                    self.exploited.add(opp)
                    self.exploit_timer[opp] = 0
                    self.exploit_cycle[opp] = 0
                    self.last_exploit_round[opp] = self.round_counter
                    self.recent_defections[opp] = 3  # Mark that we defected
                    return False

