        if opp in self.exploited and self.exploit_timer[opp] < 3:
            return True

        # Strong cooperation signal: cooperate
        if combined > 0.88:
            return True

        # Strong defection signal: defect
        if combined < 0.2:
            return False

        # Mixed: probabilistic with reputation management
        # If we have excellent reputation, be cooperative to maintain it
        if self_rep > 0.85:
            if combined > 0.5:
                return random.random() < 0.95
            else:
                return random.random() < 0.5
        elif self_rep > 0.7:
            # Moderate reputation: balance exploitation and trust
            if combined > 0.6:
                return random.random() < 0.8
            elif combined > 0.4:
                return random.random() < 0.5
            else:
                return random.random() < 0.3
        else:
            # Low reputation: focus on rebuilding through cooperation
            if combined > 0.7:
                return random.random() < 0.9
            else:
                return random.random() < 0.4

        return False

    def observe(
        self,
        donor_id: int,
