                if len(self.trust_history[opp]) > 15:
                    self.trust_history[opp] = self.trust_history[opp][-15:]

            # If opponent retaliates after we defected, remove from exploited set
            if my_action == 'defect' and opp_action == 'defect' and opp in self.exploited:
                self.exploited.discard(opp)
                self.exploit_timer[opp] = 0
                self.exploit_cycle[opp] = 0

            # Update opponent cooperation frequency
            if opp in self.opp_coop_freq:
                n = len(self.memory[opp])
                self.opp_coop_freq[opp] = (self.opp_coop_freq[opp] * (n-1) + (1 if opp_action == 'cooperate' else 0)) / n
        else:
            # Update public behavior tracking
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.opp_public_behavior:
