                        best_candidates = [o for o in candidates if o in self.trust_history and sum(self.trust_history[o])/len(self.trust_history[o]) > 0.9 and self.recent_defections.get(o, 0) == 0]
                        if best_candidates:
                            candidate = random.choice(best_candidates)
                        else:
                            candidate = random.choice(candidates)
                        self.exploited.add(candidate)
                        self.exploit_timer[candidate] = 0
                        self.exploit_cycle[candidate] = 0

        # Clean up exploit_timer for opponents no longer in memory
        for opp in list(self.exploit_timer.keys()):
            if opp not in self.memory:
                del self.exploit_timer[opp]
                if opp in self.exploit_cycle:
                    del self.exploit_cycle[opp]

