    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.memory = {}
        self.reputation = {}
        self.defection_count = {}
        self.cooperation_count = {}
        self.opponent_actions = {}
        self.round = 0
        self.last_opponent = None
        self.my_coop_count = 0
        self.my_def_count = 0
        self.recent_my_actions = []
        self.opponent_rep_history = {}
        self.total_opponents = 0
        self.defection_streak = {}
        self.cooperation_streak = {}
        self.last_interaction_round = {}
        self.opponent_rep_current = {}
        self.forgiveness_threshold = 3
        self.exploit_threshold = 0.3
        self.coop_bias = 0.15

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        self.round += 1

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []

        # First encounter: cooperate to build trust
        if len(self.memory[opp]) == 0:
            return True

        # Second encounter: if opponent defected first time, defect to punish
        if len(self.memory[opp]) == 1:
            if self.memory[opp][0] == 0:
                return False
            else:
                return True

        # Get opponent's personal cooperation rate (recent 5)
        recent = self.memory[opp][-5:]
        personal_coop = sum(recent) / len(recent) if recent else 0.5

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Track streaks
        if opp not in self.defection_streak:
            self.defection_streak[opp] = 0
        if opp not in self.cooperation_streak:
            self.cooperation_streak[opp] = 0

        # If opponent has defected against us recently, punish
        if self.defection_count[opp] > 0:
            recent_defections = self.memory[opp][-3:]
            if 0 in recent_defections:
                self.defection_streak[opp] = sum(1 for x in recent_defections if x == 0)
                self.cooperation_streak[opp] = 0
                if self.defection_streak[opp] >= 2:
                    return False
                # Forgive after 2 consecutive cooperations
                if recent_defections == [1, 1]:
                    return True
                return False
            else:
                self.defection_streak[opp] = 0
                self.cooperation_streak[opp] = sum(1 for x in recent_defections if x == 1)
                if self.cooperation_streak[opp] >= 2:
                    return True
                return False

        # If opponent has never defected, be more trusting
        if self.defection_count[opp] == 0:
            if personal_coop > 0.5:
                return True
            if public_coop > 0.7:
                return True
            return False

        # Strong cooperation signal: both high -> cooperate
        if personal_coop > 0.8 and public_coop > 0.8:
            return True

        # If opponent is cooperative but has low public rep, still cooperate
        if personal_coop > 0.7:
            return True

        # If opponent's public rep is very high, cooperate
        if public_coop > 0.9:
            return True

        # Exploit low-reputation opponents when we have good reputation
        my_total = self.my_coop_count + self.my_def_count
        my_rep = self.my_coop_count / my_total if my_total > 0 else 0.5
        if my_rep > 0.8 and public_coop < 0.4:
            return False

        # If opponent's rep is unknown, be cautious
        if public_coop == 0.5:
            return False

        # Default to cooperation if opponent seems cooperative
        if personal_coop > 0.5 and public_coop > 0.5:
            return True

        # Otherwise defect
        return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['def'] += 1

        # Record interactions where we are involved
        if donor_id == self.agent_id:
            opp = recipient_id
            opp_action = recipient_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
            else:
                self.my_def_count += 1
                self.recent_my_actions.append(0)
        elif recipient_id == self.agent_id:
            opp = donor_id
            opp_action = donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            if recipient_action == 'cooperate':
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
            else:
                self.my_def_count += 1
                self.recent_my_actions.append(0)

        # Track reputation changes for opponents we interact with
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            if other not in self.opponent_rep_history:
                self.opponent_rep_history[other] = []
            if other in self.reputation:
                rep = self.reputation[other]
                total = rep.get('coop', 0) + rep.get('def', 0)
                if total > 0:
                    self.opponent_rep_history[other].append(rep['coop'] / total)
                else:
                    self.opponent_rep_history[other].append(0.5)
            if len(self.opponent_rep_history[other]) > 10:
                self.opponent_rep_history[other] = self.opponent_rep_history[other][-10:]

        # Keep memory bounded
        for opp in list(self.memory.keys()):
            if len(self.memory[opp]) > 30:
                self.memory[opp] = self.memory[opp][-30:]
        if len(self.recent_my_actions) > 30:
            self.recent_my_actions = self.recent_my_actions[-30:]

