        # If we observe an opponent defecting frequently, we can exploit them
        # by defecting against them if we have a good reputation.
        # Also, if we see an opponent cooperating a lot, we can also defect
        # occasionally to gain advantage while maintaining our own reputation.
        # This change aims to exploit the public reputation system more aggressively.
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Observe third-party interactions to identify exploitable agents
            donor_rep = self.reputation.get(donor_id, {'coop':0, 'def':0})
            donor_total = donor_rep.get('coop',0) + donor_rep.get('def',0)
            donor_coop_rate = donor_rep.get('coop',0) / donor_total if donor_total > 0 else 0.5
            recipient_rep = self.reputation.get(recipient_id, {'coop':0, 'def':0})
            recipient_total = recipient_rep.get('coop',0) + recipient_rep.get('def',0)
            recipient_coop_rate = recipient_rep.get('coop',0) / recipient_total if recipient_total > 0 else 0.5

            # If an agent has very high cooperation rate against low reputation opponents,
            # they might be exploitable when we face them.
            # We can't directly change decide here, but we can store this info.
            # Here we just update a dictionary to remember their cooperation patterns.
            if donor_id not in self.opponent_rep_current:
                self.opponent_rep_current[donor_id] = []
            self.opponent_rep_current[donor_id].append(donor_coop_rate)
            if len(self.opponent_rep_current[donor_id]) > 20:
                self.opponent_rep_current[donor_id] = self.opponent_rep_current[donor_id][-20:]

            if recipient_id not in self.opponent_rep_current:
                self.opponent_rep_current[recipient_id] = []
            self.opponent_rep_current[recipient_id].append(recipient_coop_rate)
            if len(self.opponent_rep_current[recipient_id]) > 20:
                self.opponent_rep_current[recipient_id] = self.opponent_rep_current[recipient_id][-20:]

        # NEW: Adjust forgiveness threshold based on opponent's recent behavior
        # If opponent has been cooperative for a while, forgive faster
        # This encourages long-term cooperation and avoids getting stuck in defection loops
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            if other in self.memory:
                recent_actions = self.memory[other][-5:]
                coop_streak = sum(1 for x in recent_actions if x == 1)
                if coop_streak >= 3:
                    self.forgiveness_threshold = 2
                else:
                    self.forgiveness_threshold = 3

        # NEW: Occasionally cooperate even if we would normally defect, to build reputation
        # This is a small probabilistic bias towards cooperation
        if self._ctx_opponent_id is not None and self._ctx_opponent_id in self.memory:
            if len(self.memory[self._ctx_opponent_id]) > 0:
                if random.random() < self.coop_bias:
                    # Check if cooperating is safe (opponent not too aggressive)
                    if self.defection_count.get(self._ctx_opponent_id, 0) < 3:
                        # Override decision: force cooperation
                        # We'll handle this in decide by checking a flag
                        self._force_coop = True
                    else:
                        self._force_coop = False
        else:
            self._force_coop = False

    def decide(self) -> bool:
        # Check if we should force cooperation due to bias
        if hasattr(self, '_force_coop') and self._force_coop:
            self._force_coop = False
            return True

        opp = self._ctx_opponent_id
