class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.memory = {}
        self.reputation = {}
        self.defection_count = {}
        self.cooperation_count = {}
        self.opponent_actions = {}
        self.round = 0
        self.last_opponent = None
        self.my_coop_count = 0
        self.my_def_count = 0
        self.recent_my_actions = []
        self.opponent_rep_history = {}
        self.total_opponents = 0
        self.trust_scores = {}
        self.last_action = None
        self.defect_streak = 0
        self.coop_streak = 0
        self.public_defection_count = 0
        self.public_cooperation_count = 0
        self.observed_defections = {}
        self.observed_cooperations = {}
        self.last_opponent_reputation = 0.5
        self.punishment_threshold = 2
        self.exploit_threshold = 0.7
        self.victims = {}  # track whom we've exploited
        self.memory_public = {}  # store public info per opponent, more detailed

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        self.round += 1

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []

        # First encounter: cooperate to gauge opponent
        if len(self.memory[opp]) == 0:
            return True

        # Get opponent's recent behavior (last 5)
        recent = self.memory[opp][-5:]
        personal_coop = sum(recent) / len(recent) if recent else 0.5

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Combine personal and public info
        trust = personal_coop * 0.6 + public_coop * 0.4

        # Adaptive threshold based on our own reputation
        my_total = self.my_coop_count + self.my_def_count
        my_rep = self.my_coop_count / my_total if my_total > 0 else 0.5

        # Main decision logic with exploitative tendencies
        # 1. If opponent is clearly cooperative and we have high reputation, exploit them
        if my_rep > 0.8 and trust > self.exploit_threshold:
            # Check if opponent is "naive" - always cooperates regardless of our actions
            if len(recent) >= 4 and sum(recent) >= 3:
                # Exploit: defect to gain advantage while maintaining reputation
                self.punishment_threshold = max(1, self.punishment_threshold - 1)
                return False

        # 2. Punish defectors aggressively to maintain deterrence
        if recent and recent[-1] == 0:
            # If opponent defected, defect to show we're not a pushover
            self.punishment_threshold = max(1, self.punishment_threshold - 1)
            return False

        # 3. If opponent has defected multiple times, defect consistently
        if self.defection_count.get(opp, 0) >= self.punishment_threshold:
            return False

        # 4. Trust-based cooperation with lower threshold to encourage cooperation
        if trust >= 0.45:
            return True

        # 5. Strategic exploration: sometimes cooperate to gather info
        if self.round % 15 == 0:
            return True

        # 6. Default: defect to maximize short-term gain if trust is low
        return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
                if agent_id != self.agent_id:
                    self.observed_cooperations[agent_id] = self.observed_cooperations.get(agent_id, 0) + 1
            else:
                self.reputation[agent_id]['def'] += 1
                if agent_id != self.agent_id:
                    self.observed_defections[agent_id] = self.observed_defections.get(agent_id, 0) + 1

        # Track our own public reputation
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.public_cooperation_count += 1
            else:
                self.public_defection_count += 1
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.public_cooperation_count += 1
            else:
                self.public_defection_count += 1

        # Record interactions where we are involved, with detailed public info
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opp = recipient_id if donor_id == self.agent_id else donor_id
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            # Update trust score based on opponent's action, with more weight on recent
            if opp not in self.trust_scores:
                self.trust_scores[opp] = 0.5
            if opp_action == 'cooperate':
                self.trust_scores[opp] = min(1.0, self.trust_scores[opp] + 0.15)
            else:
                self.trust_scores[opp] = max(0.0, self.trust_scores[opp] - 0.25)
            self.trust_scores[opp] *= 0.98

            # Track our own actions
            if (donor_id == self.agent_id and donor_action == 'cooperate') or \
               (recipient_id == self.agent_id and recipient_action == 'cooperate'):
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
                self.coop_streak += 1
                self.defect_streak = 0
            elif (donor_id == self.agent_id and donor_action == 'defect') or \
                 (recipient_id == self.agent_id and recipient_action == 'defect'):
                self.my_def_count += 1
                self.recent_my_actions.append(0)
                self.defect_streak += 1
                self.coop_streak = 0

        # Keep memory bounded
        for opp in list(self.memory.keys()):
            if len(self.memory[opp]) > 30:
                self.memory[opp] = self.memory[opp][-30:]
        if len(self.recent_my_actions) > 30:
            self.recent_my_actions = self.recent_my_actions[-30:]

