        self.agent_id = agent_id
        self.memory = {}
        self.reputation = {}
        self.defection_count = {}
        self.cooperation_count = {}
        self.opponent_actions = {}
        self.round = 0
        self.last_opponent = None
        self.my_coop_count = 0
        self.my_def_count = 0
        self.recent_my_actions = []
        self.opponent_rep_history = {}
        self.total_opponents = 0
        self.streak = {}
        self.trust_building = {}
        self.my_public_rep = 0.5
        self.defection_observed = 0
        self.cooperation_observed = 0
        self.first_rounds = {}
        self.exploitation_targets = set()
        self.defection_tolerance = {}
        # Track my own reputation as seen by others - assume others use simple image scoring
        self.my_own_rep = 0.5
        self.my_partner_history = {}
        self.opponent_coop_streak = {}
        self.opponent_def_streak = {}
        self.opponent_total_actions = {}
        self.seen_agent_ids = set()
        self.reputation_weights = {}
        self.interaction_count = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        self.round += 1

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []
        if opp not in self.streak:
            self.streak[opp] = 0
        if opp not in self.trust_building:
            self.trust_building[opp] = 0
        if opp not in self.first_rounds:
            self.first_rounds[opp] = 0
        if opp not in self.defection_tolerance:
            self.defection_tolerance[opp] = 0
        if opp not in self.opponent_coop_streak:
            self.opponent_coop_streak[opp] = 0
        if opp not in self.opponent_def_streak:
            self.opponent_def_streak[opp] = 0
        if opp not in self.opponent_total_actions:
            self.opponent_total_actions[opp] = 0
        if opp not in self.interaction_count:
            self.interaction_count[opp] = 0

        # Track my own public reputation from observations, weighted more heavily to my recent actions
        my_rep = self.reputation.get(self.agent_id, {'coop': 0, 'def': 0})
        total = my_rep.get('coop', 0) + my_rep.get('def', 0)
        if total > 0:
            # Use more recent reputation by weighting own actions with decay
            # But we don't have timestamps, so use a simple average but boost if we've been cooperating recently
            self.my_public_rep = my_rep['coop'] / total
        else:
            self.my_public_rep = 0.5

        # First move: cooperate to build reputation
        if len(self.memory[opp]) == 0:
            return True

        # Get opponent's recent cooperation rate (last 10 with exponential decay-ish)
        recent = self.memory[opp][-10:]
        personal_coop = sum(recent) / len(recent) if recent else 0.5

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total_rep = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total_rep if total_rep > 0 else 0.5
        else:
            public_coop = 0.5

        # If opponent has defected recently, punish
        if self.memory[opp] and self.memory[opp][-1] == 0:
            self.streak[opp] += 1
            # If defected more than 1 time in a row, defect always
            if self.streak[opp] > 1:
                return False
            # Otherwise, mostly defect but occasionally forgive
            if random.random() < 0.97:
                return False
            else:
                self.streak[opp] = 0
                return True
        else:
            self.streak[opp] = 0

        # If opponent has a terrible public reputation and is a known sucker, exploit
        if public_coop < 0.2 and personal_coop < 0.3:
            # But only if they haven't exploited us back
            if self.defection_count.get(opp, 0) <= 1:
                return False  # Exploit
            else:
                # They defect back - avoid them or play cautiously
                return random.random() < 0.3  # Mostly defect

        # If I have a good public reputation, exploit low-rep opponents more aggressively
        if self.my_public_rep > 0.7 and public_coop < 0.4:
            # Be cautious if opponent has a history of defecting back
            if self.defection_count.get(opp, 0) > 1:
                # If they've defected back a lot, maybe they're not a sucker
                # Check if they have low personal coop but high defection back - avoid them
                if personal_coop < 0.2:
                    return False
                else:
                    return random.random() < 0.4
            # If they've never defected back, exploit aggressively
            if self.defection_count.get(opp, 0) == 0:
                # But if they have very high public rep, maybe they're a good cooperator - don't ruin relationship
                if public_coop > 0.8:
                    return True
                return False  # Exploit
            return False

        # If opponent is highly cooperative and we have a good relationship, cooperate
        if personal_coop > 0.85 and self.defection_count.get(opp, 0) == 0:
            return True

        # If opponent has high public rep and is cooperative, cooperate
        if public_coop > 0.9 and personal_coop > 0.7:
            return True

        # If opponent is a consistent cooperator (over 90% personal and public >0.8), exploit them
        if personal_coop > 0.9 and public_coop > 0.8:
            # But only if we haven't been punished for exploiting before
            if self.defection_count.get(opp, 0) <= 1:
                self.exploitation_targets.add(opp)
                return False  # Exploit

        # For moderate opponents, cooperate if they've been cooperative and have decent rep
        if personal_coop > 0.6 and public_coop > 0.5:
            return True

        # If opponent has low public rep but has been cooperative with us, trust them
        if public_coop < 0.3 and personal_coop > 0.7:
            return True

        # If opponent has high public rep but we've seen them defect recently, defect
        if public_coop > 0.7 and self.memory[opp] and self.memory[opp][-1] == 0:
            return False

        # Default: defect more often but with occasional forgiveness
        if random.random() < 0.35:
            return True
        return False

