    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.memory = {}
        self.reputation = {}
        self.defection_count = {}
        self.cooperation_count = {}
        self.opponent_actions = {}
        self.round = 0
        self.last_opponent = None
        self.my_coop_count = 0
        self.my_def_count = 0
        self.recent_my_actions = []
        self.opponent_rep_history = {}
        self.total_opponents = 0
        self.defection_streak = {}
        self.cooperation_streak = {}
        self.last_interaction_round = {}
        self.opponent_rep_current = {}
        self.third_party_rep = {}
        self.punishment_threshold = {}
        self.defection_rounds = {}
        self.cooperation_rounds = {}
        self.my_recent_actions = []
        self.partner_rep_delta = {}
        self.exploit_count = {}
        self.defection_penalty = {}
        self.cooperation_bonus = {}
        # NEW: Track our own public reputation as seen by others (approximation)
        self.my_public_rep_estimate = 0.5
        self.my_action_history = []  # Full history of our actions

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        self.round += 1

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []

        # First encounter: cooperate unless opponent has very bad reputation
        if len(self.memory[opp]) == 0:
            if opp in self.reputation:
                rep = self.reputation[opp]
                total = rep.get('coop', 0) + rep.get('def', 0)
                public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
                if public_coop < 0.25:
                    return False
            return True

        # Second encounter: if opponent defected first time, defect to punish
        if len(self.memory[opp]) == 1:
            if self.memory[opp][0] == 0:
                return False
            else:
                return True

        # Get opponent's personal cooperation rate (recent 8)
        recent = self.memory[opp][-8:]
        personal_coop = sum(recent) / len(recent) if recent else 0.5

        # Get opponent's public reputation
        if opp in self.reputation:
            rep = self.reputation[opp]
            total = rep.get('coop', 0) + rep.get('def', 0)
            public_coop = rep.get('coop', 0) / total if total > 0 else 0.5
        else:
            public_coop = 0.5

        # Track streaks
        if opp not in self.defection_streak:
            self.defection_streak[opp] = 0
        if opp not in self.cooperation_streak:
            self.cooperation_streak[opp] = 0

        # NEW: Adaptive strategy based on opponent's behavior and our reputation
        # If we have a high public reputation, we can afford to exploit more
        my_total = self.my_coop_count + self.my_def_count
        my_rep = self.my_coop_count / my_total if my_total > 0 else 0.5

        # If we have a low reputation, cooperate more to rebuild it
        if my_rep < 0.4:
            # Rebuild reputation by cooperating with anyone who isn't a hard defector
            if personal_coop < 0.3 and public_coop < 0.3:
                return False
            return True

        # If opponent has defected against us recently, punish with longer memory
        if self.defection_count[opp] > 0:
            recent_defections = self.memory[opp][-5:]
            if 0 in recent_defections:
                self.defection_streak[opp] = sum(1 for x in recent_defections if x == 0)
                self.cooperation_streak[opp] = 0
                if self.defection_streak[opp] >= 2:
                    return False
                # Forgive after 3 consecutive cooperations (more forgiving)
                if len(recent_defections) >= 3 and all(x == 1 for x in recent_defections[-3:]):
                    return True
                return False
            else:
                self.defection_streak[opp] = 0
                self.cooperation_streak[opp] = sum(1 for x in recent_defections if x == 1)
                if self.cooperation_streak[opp] >= 3:
                    return True
                return False

        # If opponent has never defected, be more trusting
        if self.defection_count[opp] == 0:
            if personal_coop > 0.4:
                return True
            if public_coop > 0.6:
                return True
            return False

        # Strong cooperation signal: both high -> cooperate
        if personal_coop > 0.7 and public_coop > 0.7:
            return True

        # If opponent is cooperative but has low public rep, still cooperate
        if personal_coop > 0.6:
            return True

        # If opponent's public rep is very high, cooperate
        if public_coop > 0.85:
            return True

        # NEW: Exploit low-reputation opponents more aggressively when we have good reputation
        if my_rep > 0.7 and public_coop < 0.5:
            return False

        # NEW: Exploit naive cooperators more aggressively
        if opp in self.third_party_rep and len(self.third_party_rep[opp]) >= 6:
            observed_coop = sum(self.third_party_rep[opp]) / len(self.third_party_rep[opp])
            if my_rep > 0.6 and observed_coop > 0.7:
                # Defect more often, but keep some cooperation to maintain reputation
                recent_my_coop = sum(self.my_recent_actions[-10:]) / max(1, len(self.my_recent_actions[-10:]))
                if recent_my_coop > 0.5:
                    # With high reputation, defect more often
                    if public_coop > 0.6:
                        return False
                    # Otherwise alternate
                    if len(self.my_recent_actions) % 2 == 0:
                        return False
                    return True

        # NEW: Use punishment threshold to identify and exploit weak opponents
        if opp in self.punishment_threshold and self.punishment_threshold[opp] >= 3:
            # This opponent has been punished multiple times, likely weak
            if my_rep > 0.6:
                return False

        # If opponent's rep is unknown, be cautious
        if public_coop == 0.5:
            return False

        # Default to cooperation if opponent seems cooperative
        if personal_coop > 0.4 and public_coop > 0.4:
            return True

        # Otherwise defect
        return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['def'] += 1

        # Record third-party cooperation patterns
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.third_party_rep:
                    self.third_party_rep[agent_id] = []
                coop_val = 1 if action == 'cooperate' else 0
                self.third_party_rep[agent_id].append(coop_val)
                if len(self.third_party_rep[agent_id]) > 25:
                    self.third_party_rep[agent_id] = self.third_party_rep[agent_id][-25:]

        # Record interactions where we are involved
        if donor_id == self.agent_id:
            opp = recipient_id
            opp_action = recipient_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
                self.cooperation_rounds[opp] = self.round
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
                self.defection_rounds[opp] = self.round
            if donor_action == 'cooperate':
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
            else:
                self.my_def_count += 1
                self.recent_my_actions.append(0)
            self.my_recent_actions.append(1 if donor_action == 'cooperate' else 0)
            self.my_action_history.append(1 if donor_action == 'cooperate' else 0)
            if len(self.my_recent_actions) > 30:
                self.my_recent_actions = self.my_recent_actions[-30:]
        elif recipient_id == self.agent_id:
            opp = donor_id
            opp_action = donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
                self.cooperation_rounds[opp] = self.round
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
                self.defection_rounds[opp] = self.round
            if recipient_action == 'cooperate':
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
            else:
                self.my_def_count += 1
                self.recent_my_actions.append(0)
            self.my_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            self.my_action_history.append(1 if recipient_action == 'cooperate' else 0)
            if len(self.my_recent_actions) > 30:
                self.my_recent_actions = self.my_recent_actions[-30:]

        # Track our own public reputation estimate based on our actions
        if len(self.my_action_history) > 0:
            recent_actions = self.my_action_history[-20:]  # Recent 20 actions
            self.my_public_rep_estimate = sum(recent_actions) / len(recent_actions)

        # Track reputation changes for opponents we interact with
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            if other not in self.opponent_rep_history:
                self.opponent_rep_history[other] = []
            if other in self.reputation:
                rep = self.reputation[other]
                total = rep.get('coop', 0) + rep.get('def', 0)
                if total > 0:
                    self.opponent_rep_history[other].append(rep['coop'] / total)
                else:
                    self.opponent_rep_history[other].append(0.5)
            if len(self.opponent_rep_history[other]) > 12:
                self.opponent_rep_history[other] = self.opponent_rep_history[other][-12:]

        # Keep memory bounded
        for opp in list(self.memory.keys()):
            if len(self.memory[opp]) > 35:
                self.memory[opp] = self.memory[opp][-35:]
        if len(self.recent_my_actions) > 30:
            self.recent_my_actions = self.recent_my_actions[-30:]

        # Track current reputation of opponents and adjust our behavior
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            donor_rep = self.reputation.get(donor_id, {'coop':0, 'def':0})
            donor_total = donor_rep.get('coop',0) + donor_rep.get('def',0)
            donor_coop_rate = donor_rep.get('coop',0) / donor_total if donor_total > 0 else 0.5
            recipient_rep = self.reputation.get(recipient_id, {'coop':0, 'def':0})
            recipient_total = recipient_rep.get('coop',0) + recipient_rep.get('def',0)
            recipient_coop_rate = recipient_rep.get('coop',0) / recipient_total if recipient_total > 0 else 0.5

            if donor_id not in self.opponent_rep_current:
                self.opponent_rep_current[donor_id] = []
            self.opponent_rep_current[donor_id].append(donor_coop_rate)
            if len(self.opponent_rep_current[donor_id]) > 25:
                self.opponent_rep_current[donor_id] = self.opponent_rep_current[donor_id][-25:]

            if recipient_id not in self.opponent_rep_current:
                self.opponent_rep_current[recipient_id] = []
            self.opponent_rep_current[recipient_id].append(recipient_coop_rate)
            if len(self.opponent_rep_current[recipient_id]) > 25:
                self.opponent_rep_current[recipient_id] = self.opponent_rep_current[recipient_id][-25:]

            if donor_action == 'defect' and recipient_coop_rate < 0.3:
                if donor_id not in self.punishment_threshold:
                    self.punishment_threshold[donor_id] = 0
                self.punishment_threshold[donor_id] += 1

        # Track reputation changes for potential exploitation
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.partner_rep_delta:
                    self.partner_rep_delta[agent_id] = []
                if agent_id in self.reputation:
                    rep = self.reputation[agent_id]
                    total = rep.get('coop',0) + rep.get('def',0)
                    current_rate = rep.get('coop',0) / total if total > 0 else 0.5
                    self.partner_rep_delta[agent_id].append(current_rate)
                    if len(self.partner_rep_delta[agent_id]) > 12:
                        self.partner_rep_delta[agent_id] = self.partner_rep_delta[agent_id][-12:]

        # Track defection penalties and cooperation bonuses for opponents
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                if donor_id not in self.defection_penalty:
                    self.defection_penalty[donor_id] = 0
                self.defection_penalty[donor_id] += 1
            if donor_action == 'cooperate':
                if donor_id not in self.cooperation_bonus:
                    self.cooperation_bonus[donor_id] = 0
                self.cooperation_bonus[donor_id] += 1
            if recipient_action == 'defect':
                if recipient_id not in self.defection_penalty:
                    self.defection_penalty[recipient_id] = 0
                self.defection_penalty[recipient_id] += 1
            if recipient_action == 'cooperate':
                if recipient_id not in self.cooperation_bonus:
                    self.cooperation_bonus[recipient_id] = 0
                self.cooperation_bonus[recipient_id] += 1

        # NEW: Update our reputation estimate based on all our actions
        # We assume our public reputation is reflected by our recent cooperation rate
        if len(self.my_action_history) >= 5:
            recent_actions = self.my_action_history[-10:]
            self.my_public_rep_estimate = sum(recent_actions) / len(recent_actions)

