                    return False

        # NEW: If opponent has cooperated every time we've interacted, exploit more often
        if self.cooperation_count.get(opp, 0) > 0 and self.defection_count.get(opp, 0) == 0:
            if len(self.memory[opp]) > 3:
                return False

        # Otherwise, defect more often but with occasional forgiveness
        if random.random() < 0.30:
            return True
        return False

