        self.opponent_recent_defect_streak = {}
        # New: track how many times we've cooperated after defecting against an opponent
        self.coop_after_defect_count = {}
        # New: track if we've been punished for defecting (opponent defects next round)
        self.punished_for_defect = {}
        # New: track opponent's cooperation rate in last 10 interactions with us
        self.recent_personal_coop = {}

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.last_opponent = opp
        self.round += 1

        if opp not in self.memory:
            self.memory[opp] = []
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self.cooperation_count:
            self.cooperation_count[opp] = 0
        if opp not in self.opponent_actions:
            self.opponent_actions[opp] = []
        if opp not in self.recent_opponent_coop:
            self.recent_opponent_coop[opp] = []
        if opp not in self.opponent_defect_after_our_coop:
            self.opponent_defect_after_our_coop[opp] = 0
        if opp not in self.opponent_response_to_my_defect:
            self.opponent_response_to_my_defect[opp] = []
        if opp not in self.opponent_response_to_my_coop:
            self.opponent_response_to_my_coop[opp] = []
