                # Limit exploitation to avoid revenge: alternate defection and cooperation
                # but defect more often if we have a strong reputation
                if self.exploit_balance[opp] < 5 and self.round % 2 == 0:
                    self.exploit_balance[opp] += 1
                    self.last_action = False
                    return False
                else:
