        if opp not in self.opponent_exploitation:
            self.opponent_exploitation[opp] = 0

        # If we've seen this opponent cooperate a lot in third-party interactions
        # and we have a good reputation, defect to gain advantage.
        if opp in self.third_party_rep and len(self.third_party_rep[opp]) >= 5:
            observed_coop = sum(self.third_party_rep[opp]) / len(self.third_party_rep[opp])
            if my_rep > 0.6 and observed_coop > 0.7 and public_coop > 0.5:
                if self.exploit_count[opp] < 4:
                    self.exploit_count[opp] += 1
                    self.last_action = False
                    return False
                else:
                    if self.round % 3 != 0:
                        self.last_action = False
                        return False
                    else:
                        self.last_action = True
                        return True

        # NEW: Exploit opponents with high cooperation streaks against third parties
        # If opponent has a long coop streak in memory, they are likely to cooperate again
        if self.opponent_coop_streak.get(opp, 0) >= 3 and my_rep > 0.7:
            # Defect to exploit, but not too often to avoid retaliation
            if self.exploit_count.get(opp, 0) < 3:
                self.exploit_count[opp] = self.exploit_count.get(opp, 0) + 1
                self.last_action = False
                return False

        # NEW: If opponent has a long defection streak, avoid them (defect to minimize loss)
        if self.opponent_def_streak.get(opp, 0) >= 3:
            self.last_action = False
            return False

        # If opponent's rep is unknown, be cautious
        if public_coop == 0.5:
            self.last_action = False
            return False

        # Default to cooperation if opponent seems cooperative
        if personal_coop > 0.5 and public_coop > 0.5:
            self.last_action = True
            return True

        # Otherwise defect
        self.last_action = False
        return False

    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['def'] += 1

        # Record third-party cooperation patterns
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.third_party_rep:
                    self.third_party_rep[agent_id] = []
                coop_val = 1 if action == 'cooperate' else 0
                self.third_party_rep[agent_id].append(coop_val)
                if len(self.third_party_rep[agent_id]) > 20:
                    self.third_party_rep[agent_id] = self.third_party_rep[agent_id][-20:]

        # Track interactions where we are involved
        if donor_id == self.agent_id:
            opp = recipient_id
            opp_action = recipient_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
                self.recent_my_actions.append(1)
