                self.recent_coop_count += 1
                self.recent_actions_window.append(1)
            else:
                self.my_def_count += 1
                self.recent_my_actions.append(0)
                self.my_def_with_opp[opp] = self.my_def_with_opp.get(opp, 0) + 1
                self.recent_actions_window.append(0)
            self.recent_total_count += 1
            self.last_action = True if donor_action == 'cooperate' else False
            self.last_opponent_action = 1 if opp_action == 'cooperate' else 0
            # Track opponent's recent behavior toward us
            if opp not in self.opponent_recent_10:
                self.opponent_recent_10[opp] = []
            self.opponent_recent_10[opp].append(1 if opp_action == 'cooperate' else 0)
            if len(self.opponent_recent_10[opp]) > 10:
                self.opponent_recent_10[opp] = self.opponent_recent_10[opp][-10:]
            if opp not in self.total_interactions:
                self.total_interactions[opp] = 0
            self.total_interactions[opp] += 1
        elif recipient_id == self.agent_id:
            opp = donor_id
            opp_action = donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation_count.get(opp, 0) + 1
            else:
                self.defection_count[opp] = self.defection_count.get(opp, 0) + 1
            if recipient_action == 'cooperate':
                self.my_coop_count += 1

