    def observe(self, donor_id, donor_action, recipient_id, recipient_action) -> None:
        # Update reputation for all observed agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = {'coop': 0, 'def': 0}
            if action == 'cooperate':
                self.reputation[agent_id]['coop'] += 1
            else:
                self.reputation[agent_id]['def'] += 1

        # Record third-party cooperation patterns
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent_id not in self.third_party_rep:
                    self.third_party_rep[agent_id] = []
                coop_val = 1 if action == 'cooperate' else 0
                self.third_party_rep[agent_id].append(coop_val)
                if len(self.third_party_rep[agent_id]) > 20:
                    self.third_party_rep[agent_id] = self.third_party_rep[agent_id][-20:]

        # Track interactions where we are involved
        if donor_id == self.agent_id:
            opp = recipient_id
            opp_action = recipient_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
