            if opp not in self.opponent_recent_defects:
                self.opponent_recent_defects[opp] = []
            self.opponent_recent_defects[opp].append(1 if opp_action == 'defect' else 0)
            if len(self.opponent_recent_defects[opp]) > 3:
                self.opponent_recent_defects[opp] = self.opponent_recent_defects[opp][-3:]
        elif recipient_id == self.agent_id:
            opp = donor_id
            opp_action = donor_action
            if opp not in self.memory:
                self.memory[opp] = []
            self.memory[opp].append(1 if opp_action == 'cooperate' else 0)
            if opp_action == 'cooperate':
                self.cooperation_count[opp] = self.cooperation
